from scipy.ndimage import map_coordinates
p=.227185/1024;f=2344.588379;z=.5998;u=np.arange(1024);v=np.arange(1024);y=.1135925-(u+.5)*p;x=.0135925-(v+.5)*p;cu=512-f*y/z;cv=512+f*(-x-.1)/z;grid=np.meshgrid(cv,cu,indexing='ij')
def get(n):
 src=np.asarray(Image.open(f'/app/output/after_{n:02d}/last/canvas_cam.jpg'));ink=np.max(src,axis=2)<90;return map_coordinates(ink.astype(float),grid,order=0)>0.5
G=np.asarray(Image.open('/app/target.png'))[:,:,0]<100
for n,prev,roi in [(11,10,np.s_[650:780,300:380]),(12,11,np.s_[640:730,370:435]),(13,12,np.s_[630:710,430:485])]:
 A=get(n)&~get(prev);best=(-1,None,None)
